Cards are grouped by pharmacological class, in the same order as my class slides; switch Group by to Condition treated to study by indication instead. Pick a study mode, narrow the deck to one class, and click the card (or press Space) to flip it. Mark each card Got it or Still learning. Your progress is saved in this browser, and Only still learning drills just the cards you have not mastered yet.
Keyboard: Space flip · ← → previous / next · K got it · L still learning
fc = import(new URL("../../flashcards.js?v=2026-10-20b", document.baseURI).href)
flashcards = fc.flashcards
esc = fc.esc
meds = FileAttachment("top200medications.csv").csv()
legend = FileAttachment("Legend.csv").csv()
flashcards({
  cards: meds,
  storageKey: "pharmtech-top200-known",
  idField: "generic",
  groupings: [
    { label: "Drug class", field: "pharm_class", orderField: "class_order" },
    { label: "Condition treated", field: "group", orderField: "condition_order" }
  ],
  searchFields: ["generic", "brand", "pharm_class", "drug_class", "indication", "notes"],
  placeholder: "Drug, brand, class, or interaction",
  invalidation,
  modes: {
    generic: {
      label: "Generic → Brand, class, use",
      front: d =&gt; `&lt;div class="fc-kicker"&gt;Generic&lt;/div&gt;&lt;div class="fc-big"&gt;${esc(d.generic)}&lt;/div&gt;`,
      back: d =&gt; details(d, "brand")
    },
    brand: {
      label: "Brand → Generic",
      front: d =&gt; `&lt;div class="fc-kicker"&gt;Brand&lt;/div&gt;&lt;div class="fc-big"&gt;${esc(d.brand)}&lt;/div&gt;`,
      back: d =&gt; details(d, "generic")
    },
    class: {
      label: "Generic → Class & indication",
      hideGroupOnFront: true,
      front: d =&gt; `&lt;div class="fc-kicker"&gt;What class is it, and what is it for?&lt;/div&gt;&lt;div class="fc-big"&gt;${esc(d.generic)}&lt;/div&gt;`,
      back: d =&gt; `&lt;div class="fc-big fc-mid"&gt;${esc(d.drug_class)}&lt;/div&gt;&lt;div class="fc-row"&gt;${esc(d.indication)}&lt;/div&gt;`
    },
    watch: {
      label: "Generic → Watch out for (interactions, storage)",
      front: d =&gt; `&lt;div class="fc-kicker"&gt;What should you watch out for?&lt;/div&gt;&lt;div class="fc-big"&gt;${esc(d.generic)}&lt;/div&gt;&lt;div class="fc-row"&gt;${esc(d.brand)}&lt;/div&gt;`,
      back: d =&gt; d.notes
        ? `&lt;div class="fc-kicker"&gt;Watch out&lt;/div&gt;&lt;div class="fc-row fc-answer"&gt;${esc(d.notes)}&lt;/div&gt;`
        : `&lt;div class="fc-row"&gt;No special interaction or storage notes. Know the class and use: &lt;strong&gt;${esc(d.drug_class)}&lt;/strong&gt;, ${esc(d.indication)}.&lt;/div&gt;`
    }
  }
})
statusClass = s =&gt; s.startsWith("C-") ? "fc-ctrl" : s.startsWith("OTC") ? "fc-otc" : "fc-rx"
details = (d, lead) =&gt; `
  &lt;div class="fc-kicker"&gt;${lead === "brand" ? "Brand" : "Generic"}&lt;/div&gt;
  &lt;div class="fc-big fc-mid"&gt;${esc(lead === "brand" ? d.brand : d.generic)}&lt;/div&gt;
  &lt;dl class="fc-dl"&gt;
    &lt;dt&gt;Class&lt;/dt&gt;&lt;dd&gt;${esc(d.drug_class)}&lt;/dd&gt;
    &lt;dt&gt;Used for&lt;/dt&gt;&lt;dd&gt;${esc(d.indication)}&lt;/dd&gt;
    &lt;dt&gt;Status&lt;/dt&gt;&lt;dd&gt;&lt;span class="fc-badge ${statusClass(d.status)}"&gt;${esc(d.status)}&lt;/span&gt;&lt;/dd&gt;
    ${d.notes ? `&lt;dt&gt;Watch out&lt;/dt&gt;&lt;dd class="fc-note"&gt;${esc(d.notes)}&lt;/dd&gt;` : ""}
  &lt;/dl&gt;`
For laws, sig codes, storage, and calculations, see the PTCB review deck.

